// src/desktop-preload.ts
import { ipcRenderer } from "electron";

// src/lib/electron-ipc.ts
var MANAGED_AUTH_IPC = {
  openExternal: "managed-auth:open-external",
  redirectTarget: "managed-auth:redirect-target",
  deepLink: "managed-auth:deep-link"
};

// src/desktop-preload.ts
function createManagedAuthBridge() {
  return {
    openExternal: (url) => ipcRenderer.invoke(MANAGED_AUTH_IPC.openExternal, url),
    onDeepLink: (callback) => {
      const listener = (_event, url) => callback(url);
      ipcRenderer.on(MANAGED_AUTH_IPC.deepLink, listener);
      return () => {
        ipcRenderer.removeListener(MANAGED_AUTH_IPC.deepLink, listener);
      };
    },
    getRedirectTarget: () => ipcRenderer.invoke(MANAGED_AUTH_IPC.redirectTarget)
  };
}
export {
  createManagedAuthBridge
};
